        // breaks the tag: fields, key id, version, tag itself.
        let tampered = [
            base.replace("\"x\"", "\"y\""),
            base.replace("\"id\"", "\"id2\""),
            base.replace("\"key_version\":1", "\"key_version\":2"),
            base.replace(&sign_tag(key, "id", 1, &["x"]), &"a".repeat(64)),
